ALTER TABLE public.posts ADD COLUMN author_deleted boolean NOT NULL DEFAULT false;
ALTER TABLE public.posts ADD COLUMN admin_removed boolean NOT NULL DEFAULT false;
ALTER TABLE public.comments ADD COLUMN admin_removed boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.posts.is_deleted IS 'DEPRECATED: use author_deleted and admin_removed';
CREATE OR REPLACE FUNCTION public.guard_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.admin_removed AND NOT NEW.admin_removed THEN RAISE EXCEPTION 'Cannot restore moderation removal'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND NEW.admin_removed IS DISTINCT FROM OLD.admin_removed THEN RAISE EXCEPTION 'Admin only'; END IF; IF TG_TABLE_NAME='posts' THEN IF OLD.author_deleted AND NOT NEW.author_deleted THEN RAISE EXCEPTION 'Cannot restore deleted post'; END IF; IF NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.pseudonym IS DISTINCT FROM OLD.pseudonym THEN RAISE EXCEPTION 'Protected fields'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_posts BEFORE UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.guard_removal();
CREATE TRIGGER guard_comments BEFORE UPDATE ON public.comments FOR EACH ROW EXECUTE FUNCTION public.guard_removal();
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, recipient_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','blocked','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id), UNIQUE(sender_id,recipient_id));
GRANT SELECT(id,status,created_at,updated_at) ON public.conversations TO authenticated;
GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_chat_member(_id uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversations WHERE id=_id AND (sender_id=_user OR recipient_id=_user)) $$;
CREATE POLICY "participants view conversations" ON public.conversations FOR SELECT TO authenticated USING (public.is_chat_member(id,auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id), sender_id uuid NOT NULL, body text NOT NULL CHECK(char_length(trim(body)) BETWEEN 1 AND 2000), is_request boolean NOT NULL DEFAULT false, admin_removed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT(id,conversation_id,body,is_request,admin_removed,created_at) ON public.messages TO authenticated;
GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "participants view messages" ON public.messages FOR SELECT TO authenticated USING (public.is_chat_member(conversation_id,auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.blocks (blocker_id uuid NOT NULL,blocked_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
GRANT ALL ON public.blocks TO service_role;
ALTER TABLE public.blocks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.conversation_reads (conversation_id uuid NOT NULL REFERENCES public.conversations(id), user_id uuid NOT NULL,last_read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
GRANT ALL ON public.conversation_reads TO service_role;
ALTER TABLE public.conversation_reads ENABLE ROW LEVEL SECURITY;
CREATE INDEX messages_conversation_idx ON public.messages(conversation_id,created_at);
CREATE OR REPLACE FUNCTION public.request_message(_target_type text,_target_id uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid:=auth.uid(); other_id uuid; cid uuid; BEGIN IF me IS NULL OR public.is_banned(me) OR _target_type NOT IN ('post','comment') OR _target_id IS NULL OR char_length(trim(_body)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF _target_type='post' THEN SELECT author_id INTO other_id FROM public.posts WHERE id=_target_id AND NOT (is_deleted OR author_deleted OR admin_removed) AND (expires_at IS NULL OR expires_at>now()); ELSE SELECT c.author_id INTO other_id FROM public.comments c JOIN public.posts p ON p.id=c.post_id WHERE c.id=_target_id AND NOT (c.is_deleted OR c.admin_removed OR p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now()); END IF; IF other_id IS NULL OR other_id=me OR public.is_banned(other_id) OR EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=me AND blocked_id=other_id) OR (blocker_id=other_id AND blocked_id=me)) OR EXISTS(SELECT 1 FROM public.conversations WHERE (sender_id=me AND recipient_id=other_id) OR (sender_id=other_id AND recipient_id=me)) THEN RAISE EXCEPTION 'Request unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtext(me::text)); IF (SELECT count(*) FROM public.conversations WHERE sender_id=me AND created_at>=now()-interval '1 day')>=5 THEN RAISE EXCEPTION 'Daily request limit reached'; END IF; INSERT INTO public.conversations(sender_id,recipient_id) VALUES(me,other_id) RETURNING id INTO cid; INSERT INTO public.messages(conversation_id,sender_id,body,is_request) VALUES(cid,me,trim(_body),true); RETURN cid; END $$;
CREATE OR REPLACE FUNCTION public.list_my_conversations() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'mine',c.sender_id=auth.uid(),'pseudonym',coalesce(p.pseudonym,'Someone'),'created_at',c.created_at,'unread',(SELECT count(*) FROM public.messages m WHERE m.conversation_id=c.id AND m.sender_id<>auth.uid() AND m.created_at>coalesce((SELECT last_read_at FROM public.conversation_reads WHERE conversation_id=c.id AND user_id=auth.uid()),'epoch'::timestamptz)),'last_message',(SELECT CASE WHEN m.admin_removed THEN '[Removed]' ELSE m.body END FROM public.messages m WHERE m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1)) ORDER BY c.updated_at DESC),'[]'::jsonb) FROM public.conversations c LEFT JOIN public.profiles p ON p.id=CASE WHEN c.sender_id=auth.uid() THEN c.recipient_id ELSE c.sender_id END WHERE auth.uid() IS NOT NULL AND (c.sender_id=auth.uid() OR c.recipient_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.read_conversation(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_chat_member(_id,auth.uid()) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; INSERT INTO public.conversation_reads(conversation_id,user_id,last_read_at) VALUES(_id,auth.uid(),now()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET last_read_at=excluded.last_read_at; SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',CASE WHEN m.admin_removed THEN '[Removed by admin]' ELSE m.body END,'mine',m.sender_id=auth.uid(),'is_request',m.is_request,'created_at',m.created_at) ORDER BY m.created_at),'[]'::jsonb) INTO result FROM public.messages m WHERE m.conversation_id=_id; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.respond_to_request(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.conversations%ROWTYPE; BEGIN SELECT * INTO c FROM public.conversations WHERE id=_id FOR UPDATE; IF c.recipient_id IS DISTINCT FROM auth.uid() OR c.status<>'pending' OR _status NOT IN ('accepted','declined','blocked') THEN RAISE EXCEPTION 'Request unavailable'; END IF; UPDATE public.conversations SET status=_status,updated_at=now() WHERE id=_id; IF _status='blocked' THEN INSERT INTO public.blocks(blocker_id,blocked_id) VALUES(auth.uid(),c.sender_id) ON CONFLICT DO NOTHING; END IF; END $$;
CREATE OR REPLACE FUNCTION public.send_chat_message(_id uuid,_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.conversations%ROWTYPE; BEGIN SELECT * INTO c FROM public.conversations WHERE id=_id FOR UPDATE; IF auth.uid() IS NULL OR public.is_banned(auth.uid()) OR c.status<>'accepted' OR auth.uid() NOT IN (c.sender_id,c.recipient_id) OR char_length(trim(_body)) NOT BETWEEN 1 AND 2000 OR EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=c.sender_id AND blocked_id=c.recipient_id) OR (blocker_id=c.recipient_id AND blocked_id=c.sender_id)) THEN RAISE EXCEPTION 'Cannot send message'; END IF; INSERT INTO public.messages(conversation_id,sender_id,body) VALUES(_id,auth.uid(),trim(_body)); UPDATE public.conversations SET updated_at=now() WHERE id=_id; END $$;
CREATE OR REPLACE FUNCTION public.block_conversation(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.conversations%ROWTYPE; BEGIN SELECT * INTO c FROM public.conversations WHERE id=_id FOR UPDATE; IF auth.uid() IS NULL OR auth.uid() NOT IN (c.sender_id,c.recipient_id) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; INSERT INTO public.blocks(blocker_id,blocked_id) VALUES(auth.uid(),CASE WHEN auth.uid()=c.sender_id THEN c.recipient_id ELSE c.sender_id END) ON CONFLICT DO NOTHING; UPDATE public.conversations SET status='blocked',updated_at=now() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.request_message(text,uuid,text),public.list_my_conversations(),public.read_conversation(uuid),public.respond_to_request(uuid,text),public.send_chat_message(uuid,text),public.block_conversation(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_message(text,uuid,text),public.list_my_conversations(),public.read_conversation(uuid),public.respond_to_request(uuid,text),public.send_chat_message(uuid,text),public.block_conversation(uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;
ALTER PUBLICATION supabase_realtime ADD TABLE public.conversations;